import{_ as n,C as i,o as t,c as o,a2 as a,b as l,w as r,a as d,E as c,a3 as h}from"./chunks/framework.Brv5O9VI.js";const b=JSON.parse('{"title":"14.12 Search, RAG & Vector AI Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.12-search-and-ai-architecture.md","filePath":"system-design/14.12-search-and-ai-architecture.md"}'),g={name:"system-design/14.12-search-and-ai-architecture.md"};function p(u,e,m,f,S,y){const s=i("Mermaid");return t(),o("div",null,[e[1]||(e[1]=a('<h1 id="_14-12-search-rag-vector-ai-architecture" tabindex="-1">14.12 Search, RAG &amp; Vector AI Architecture <a class="header-anchor" href="#_14-12-search-rag-vector-ai-architecture" aria-label="Permalink to &quot;14.12 Search, RAG &amp; Vector AI Architecture&quot;">​</a></h1><h2 id="_1-what-it-is-in-plain-words" tabindex="-1">1. What It Is in Plain Words <a class="header-anchor" href="#_1-what-it-is-in-plain-words" aria-label="Permalink to &quot;1. What It Is in Plain Words&quot;">​</a></h2><p>Search and AI architecture describes how unstructured natural language queries are matched to authoritative records—comparing dense neural embeddings, inverted keyword indexes, vector databases, and multi-stage reranking pipelines.</p><hr><h2 id="_2-how-this-project-uses-it" tabindex="-1">2. How THIS Project Uses It <a class="header-anchor" href="#_2-how-this-project-uses-it" aria-label="Permalink to &quot;2. How THIS Project Uses It&quot;">​</a></h2><p>The search pipeline is an <strong>Air-Gapped Dense Vector RAG Architecture</strong>:</p><ol><li><strong>Embedding</strong>: Transforms queries into 384-dimensional dense vectors using FastEmbed ONNX (<code>BAAI/bge-small-en-v1.5</code>) in [<code>app.py:L89</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/app.py#L89).</li><li><strong>Dense Search</strong>: Evaluates exact cosine inner products over <code>faiss.IndexFlatIP</code> in [<code>app.py:L90</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/app.py#L90) with $k=1$.</li><li><strong>Retrieval</strong>: Fetches full regulatory citations from immutable JSON records in [<code>model2_corpus.json</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/model2_corpus.json).</li><li><strong>Guardrailing</strong>: Filters low-confidence or out-of-domain queries using [<code>guardrail.py</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/guardrail.py).</li></ol>',7)),(t(),l(h,null,{default:r(()=>[c(s,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20UserQuery%5B%22Query%3A%20'Ordinary%20Portland%20Cement%2053%20Grade'%22%5D%20--%3E%20FastEmbed%5B%22FastEmbed%20ONNX%20(bge-small-en-v1.5)%22%5D%0A%20%20%20%20FastEmbed%20--%3E%7C384d%20Dense%20Vector%7C%20FAISS%5B%22FAISS%20IndexFlatIP%20Scan%22%5D%0A%20%20%20%20FAISS%20--%3E%7CInner%20Product%20Score%20%26%20Index%20ID%7C%20Candidate%5B%22Candidate%3A%20IS%2012269%3A2013%20(Score%3A%200.8421)%22%5D%0A%20%20%20%20Candidate%20--%3E%20GuardrailCheck%7B%22guardrail.py%3A%20Score%20%3E%3D%200.45%20or%20Regex%20Match%3F%22%7D%0A%20%20%20%20GuardrailCheck%20--%3E%7CYes%7C%20Valid%5B%22Retrieve%20Gazette%20Metadata%20%26%20Citations%22%5D%0A%20%20%20%20GuardrailCheck%20--%3E%7CNo%7C%20Reject%5B%22Suppress%20Audit%20Pack%20%26%20Return%20Explanation%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<hr><h2 id="_3-comparison-of-search-paradigms" tabindex="-1">3. Comparison of Search Paradigms <a class="header-anchor" href="#_3-comparison-of-search-paradigms" aria-label="Permalink to &quot;3. Comparison of Search Paradigms&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Search Architecture</th><th style="text-align:left;">Strengths</th><th style="text-align:left;">Weaknesses</th><th style="text-align:left;">Accuracy on Synonyms</th><th style="text-align:left;">Fit for Regulatory Engine</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Dense Vector RAG (FAISS)</strong> (Used)</td><td style="text-align:left;">Understands synonyms and concepts</td><td style="text-align:left;">Computationally heavier than BM25</td><td style="text-align:left;"><strong>Highest (Maps &#39;rebar&#39; to IS 1786)</strong></td><td style="text-align:left;"><strong>Optimal</strong></td></tr><tr><td style="text-align:left;"><strong>Sparse Keyword Search (BM25)</strong></td><td style="text-align:left;">Microsecond execution, exact tokens</td><td style="text-align:left;">Fails on vocabulary mismatch</td><td style="text-align:left;">Low on conceptual phrasing</td><td style="text-align:left;">Good as complementary filter</td></tr><tr><td style="text-align:left;"><strong>Hybrid Search (Dense + Sparse)</strong></td><td style="text-align:left;">Combines exact token &amp; semantic match</td><td style="text-align:left;">More complex index coordination</td><td style="text-align:left;">Highest overall</td><td style="text-align:left;">Recommended at 10,000+ standards</td></tr><tr><td style="text-align:left;"><strong>Generative LLM Synthesis (RAG)</strong></td><td style="text-align:left;">Generates natural paragraph answers</td><td style="text-align:left;">Prone to hallucinating clauses</td><td style="text-align:left;">Dangerous for statutory law</td><td style="text-align:left;">Unacceptable risk</td></tr></tbody></table><hr><h2 id="_4-trade-offs-accepted" tabindex="-1">4. Trade-offs Accepted <a class="header-anchor" href="#_4-trade-offs-accepted" aria-label="Permalink to &quot;4. Trade-offs Accepted&quot;">​</a></h2><ul><li><strong>$k=1$ Fixed Nearest Neighbor</strong>: Currently retrieves only the single highest-scoring standard, which does not represent composite hardware governed by multiple overlapping standards.</li></ul><hr><h2 id="_5-what-breaks-at-scale" tabindex="-1">5. What Breaks at Scale <a class="header-anchor" href="#_5-what-breaks-at-scale" aria-label="Permalink to &quot;5. What Breaks at Scale&quot;">​</a></h2><ul><li><strong>At 10x Load</strong>: Search time remains constant at 0.18ms.</li><li><strong>At 100x Load</strong>: FastEmbed CPU embedding becomes the primary bottleneck (not the FAISS search).</li><li><strong>At 1000x Load / 100,000 Standards</strong>: The $O(N)$ linear scan of <code>IndexFlatIP</code> rises to ~15ms; requires switching to an inverted file index (<code>IndexIVFFlat</code>) or graph index (<code>IndexHNSWFlat</code>).</li></ul><hr><h2 id="_6-how-a-senior-engineer-would-improve-it" tabindex="-1">6. How a Senior Engineer Would Improve It <a class="header-anchor" href="#_6-how-a-senior-engineer-would-improve-it" aria-label="Permalink to &quot;6. How a Senior Engineer Would Improve It&quot;">​</a></h2><p>Implement a <strong>Two-Stage Hybrid Search &amp; Reranking Pipeline</strong>:</p><ol><li><strong>Stage 1 (Retrieval)</strong>: Retrieve top-20 candidates using a reciprocal rank fusion (RRF) of BM25 (exact tokens) and FAISS (dense semantics).</li><li><strong>Stage 2 (Reranking)</strong>: Pass top-20 candidates through a lightweight Cross-Encoder model (<code>bge-reranker-small</code>) to score and surface the top-3 standards with calibrated confidence scores.</li></ol><hr><h2 id="_7-30-second-spoken-answer" tabindex="-1">7. 30-Second Spoken Answer <a class="header-anchor" href="#_7-30-second-spoken-answer" aria-label="Permalink to &quot;7. 30-Second Spoken Answer&quot;">​</a></h2><blockquote><p>&quot;We chose dense vector RAG with FastEmbed and FAISS over traditional keyword search because industrial compliance queries rely heavily on synonyms—a user searching for &#39;TMT bars&#39; needs to match the statutory title &#39;High Strength Deformed Steel Bars IS 1786&#39;. FAISS maps these semantic concepts in under zero-point-two milliseconds while completely eliminating generative LLM hallucinations.&quot;</p></blockquote>',16))])}const A=n(g,[["render",p]]);export{b as __pageData,A as default};
